-- The two checklists published on 2026-11-03: Your First Semester Away From
-- Home (College) and The First Week Home From the Hospital (Recovery).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-03`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('your-first-semester-away-from-home', 'Your First Semester Away From Home', 'For the first weeks of living away from home, when the freedom and the loneliness arrive together. It puts shape in the day, gets you into one weekly thing, sets a call home on a fixed day, and holds off judging the place too early.', 'College', '["Put your class times and one meal on the same calendar — a day with shape is easier than a day of pure freedom.", "Say yes to the first three invitations you get — early friendships come from being there, not from clicking.", "Join one thing that meets every week — a standing hour puts the same faces in front of you.", "Go to one professor''s office hours before you are stuck — asking is easier the second time than the first.", "Pick a laundry day and a food day — the small stuff is what quietly piles up into dread.", "Call home on a set day rather than when it hurts — a scheduled call interrupts the homesick spiral.", "Find the campus counseling desk before you need it — knowing where it is removes a step on a bad day.", "Wait until the sixth week to judge how it is going — the first weeks are nobody''s real experience of a place.", "Keep one habit from home going — a recipe or a team you follow keeps you recognizably yourself."]'::jsonb, 'weekly', array['Life Transitions', 'Loneliness', 'Self-Care']::text[], 1, '2026-11-03T16:00:00+00:00'::timestamptz),
  ('the-first-week-home-from-the-hospital', 'The First Week Home From the Hospital', 'For the week after you come home from a hospital stay, when the instructions blur and the days get long. It pins down the medication times, the number to call, how far to walk, and what you are watching for.', 'Recovery', '["Write the discharge instructions on one sheet by the bed — nobody remembers what was said on the way out.", "Set the medication times as alarms — recovery is the worst week to be remembering doses.", "Put the number for questions somewhere visible — a question at nine at night should not wait for Monday.", "Accept the first offer of help that arrives — people stop offering somewhere around day four.", "Walk whatever distance you were told and no further — extra on a good day costs you the next two.", "Write a line about how each day went — a flat Thursday makes sense beside a hard Tuesday.", "Keep the list of signs you were told to call about — a written list beats deciding while worried.", "Put one thing to look forward to in each day — a week of nothing but recovery gets very long.", "Book the follow-up appointment this week — it is easier to arrange now than when you feel better."]'::jsonb, 'daily', array['Body', 'Self-Care', 'Resilience']::text[], 1, '2026-11-03T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
